import re
lines=[l.strip() for l in open("rep_text.txt",encoding="utf-8").read().split("\n") if l.strip()]
cur=[]
def flush(seg,start):
    if len(seg)>=2: print(f"--- 行{start}")
    for n,t in seg: print(f"   {n:>3}  {t[:56]}")
for i,l in enumerate(lines):
    m=re.match(r'^(\[?\d+\]?[\.\)、])\s*(.*)',l)
    if m and not re.match(r'^(http|www)',l):
        num=re.sub(r'\D','',m.group(1))
        cur.append((int(num),m.group(2)))
    else:
        if len(cur)>=2: flush(cur,i)
        cur=[]
if len(cur)>=2: flush(cur,len(lines))
EOF

