  }
  $out += "--- 图片宽度 ---"
  foreach ($s in $doc.InlineShapes) { $out += ("  图: 宽 {0:N1}pt ({1:N2}cm) {2}" -f $s.Width, ($s.Width/28.35), $(if ($s.Width -gt $usable) {"<<超宽"} else {"OK"})) }
  $out | Set-Content "C:\Users\Administrator\AppData\Local\Temp\fmt.txt" -Encoding UTF8
  $doc.Close(0)
} catch { "ERR: " + $_.Exception.Message }
try { $app.Quit() } catch {}

