import docx
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

p = "合并预览_含VPN章.docx"
d = docx.Document(p)

def add_after(trPr, el, order):
    # 按 schema 顺序插入
    for child in list(trPr):
        if child.tag in order:
            child.addprevious(el)
            return
    trPr.append(el)

n = 0
for ti, t in enumerate(d.tables):
    if ti == 0:
        continue  # 封面信息表不处理
    for i, row in enumerate(t.rows):
        trPr = row._tr.get_or_add_trPr()
        if trPr.find(qn("w:cantSplit")) is None:
            el = OxmlElement("w:cantSplit")
            trPr.insert(0, el)
        if i == 0 and trPr.find(qn("w:tblHeader")) is None:
            h = OxmlElement("w:tblHeader")
            cant = trPr.find(qn("w:cantSplit"))
            if cant is not None:
                cant.addnext(h)
            else:
                trPr.append(h)
        n += 1
print("处理行数", n)
d.save(p)
PYEOF

